def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 3 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            minr = min(y for y, x in cells)
            minc = min(x for y, x in cells)
            shape = frozenset((y-minr, x-minc) for y, x in cells)
            objects.append((color, cells, shape))

    # If identical shapes occur in different colors, use the color that has
    # the stronger presence elsewhere in the grid.
    counts = {}
    for color, cells, _ in objects:
        counts[color] = counts.get(color, 0) + len(cells)

    out = [row[:] for row in grid]
    for i, (color, cells, shape) in enumerate(objects):
        matches = [other_color for other_color, _, other_shape in objects
                   if other_shape == shape and other_color != color]
        if matches:
            replacement = max(matches, key=lambda x: counts.get(x, 0))
            if counts.get(replacement, 0) > counts.get(color, 0):
                for r, c in cells:
                    out[r][c] = replacement
    return out
